stream_by_asset_time.map:
function (doc) {
  if (doc.asset_id && doc.timestamp !== undefined && doc.timestamp !== null) {
    emit([doc.asset_id, doc.timestamp], null);
  }
}

stream_by_asset_sensor_time.map:
function (doc) {
  if (!doc.asset_id || doc.timestamp === undefined || doc.timestamp === null) return;
  var reserved = {_id: 1, _rev: 1, asset_id: 1, timestamp: 1, dataset: 1, type: 1, doctype: 1};
  for (var field in doc) {
    if (!reserved[field] && doc[field] !== undefined && doc[field] !== null) {
      emit([doc.asset_id, field, doc.timestamp], null);
    }
  }
}

assets_by_sensor.map:
function (doc) {
  if (!doc.asset_id || doc.timestamp === undefined || doc.timestamp === null) return;
  var reserved = {_id: 1, _rev: 1, asset_id: 1, timestamp: 1, dataset: 1, type: 1, doctype: 1};
  for (var field in doc) {
    if (!reserved[field]) emit([field, doc.asset_id], null);
  }
}

coverage_by_asset_sensor.map:
function (doc) {
  if (!doc.asset_id || doc.timestamp === undefined || doc.timestamp === null) return;
  var reserved = {_id: 1, _rev: 1, asset_id: 1, timestamp: 1, dataset: 1, type: 1, doctype: 1};
  for (var field in doc) {
    if (reserved[field]) continue;
    var nonNull = doc[field] !== undefined && doc[field] !== null;
    emit([doc.asset_id, field], {
      non_null_count: nonNull ? 1 : 0,
      first_timestamp: nonNull ? doc.timestamp : null,
      last_timestamp: nonNull ? doc.timestamp : null
    });
  }
}

coverage_by_asset_sensor.reduce:
function (keys, values, rereduce) {
  var out = {non_null_count: 0, first_timestamp: null, last_timestamp: null};
  values.forEach(function (value) {
    out.non_null_count += value.non_null_count || 0;
    if (value.first_timestamp !== null && (out.first_timestamp === null || value.first_timestamp < out.first_timestamp)) {
      out.first_timestamp = value.first_timestamp;
    }
    if (value.last_timestamp !== null && (out.last_timestamp === null || value.last_timestamp > out.last_timestamp)) {
      out.last_timestamp = value.last_timestamp;
    }
  });
  return out;
}

stats_by_asset_sensor.map:
function (doc) {
  if (!doc.asset_id || doc.timestamp === undefined || doc.timestamp === null) return;
  var reserved = {_id: 1, _rev: 1, asset_id: 1, timestamp: 1, dataset: 1, type: 1, doctype: 1};
  function statValue(value) {
    var number = null;
    if (typeof value === 'number' && isFinite(value)) {
      number = value;
    } else if (typeof value === 'string' && value.trim() !== '' && isFinite(Number(value))) {
      number = Number(value);
    }
    if (number === null) {
      return {count: 0, null_count: 1, min: null, max: null, sum: 0, sumsq: 0, first_timestamp: null, last_timestamp: null};
    }
    return {count: 1, null_count: 0, min: number, max: number, sum: number, sumsq: number * number, first_timestamp: doc.timestamp, last_timestamp: doc.timestamp};
  }
  for (var field in doc) {
    if (!reserved[field]) emit([doc.asset_id, field], statValue(doc[field]));
  }
}

stats_by_asset_sensor.reduce:
function (keys, values, rereduce) {
  var out = {count: 0, null_count: 0, min: null, max: null, sum: 0, sumsq: 0, first_timestamp: null, last_timestamp: null};
  values.forEach(function (value) {
    var count = value.count || 0;
    out.count += count;
    out.null_count += value.null_count || 0;
    out.sum += value.sum || 0;
    out.sumsq += value.sumsq || 0;
    if (count) {
      if (out.min === null || value.min < out.min) out.min = value.min;
      if (out.max === null || value.max > out.max) out.max = value.max;
      if (value.first_timestamp !== null && (out.first_timestamp === null || value.first_timestamp < out.first_timestamp)) {
        out.first_timestamp = value.first_timestamp;
      }
      if (value.last_timestamp !== null && (out.last_timestamp === null || value.last_timestamp > out.last_timestamp)) {
        out.last_timestamp = value.last_timestamp;
      }
    }
  });
  return out;
}

